import Foundation
@testable import FlightViewCore
import XCTest

/// Runs every golden case from shared/fixtures/flightmath_fixtures.json (generated by the
/// Python reference, which is itself validated against pymap3d).
final class FixtureTests: XCTestCase {
    private var root: [String: Any] = [:]

    override func setUpWithError() throws {
        // Tests/FlightViewCoreTests/FixtureTests.swift -> repo root is six levels up.
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("shared/fixtures/flightmath_fixtures.json")
        let data = try Data(contentsOf: url)
        root = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
    }

    private func cases(_ key: String) -> [[String: Any]] { root[key] as? [[String: Any]] ?? [] }
    private func d(_ v: Any?) -> Double { (v as? NSNumber)?.doubleValue ?? .nan }
    private func dn(_ v: Any?) -> Double? { v is NSNull ? nil : (v as? NSNumber)?.doubleValue }
    private func arr(_ v: Any?) -> [Double] { (v as? [Any] ?? []).map { d($0) } }
    private func mat(_ v: Any?) -> Mat3 { Mat3((v as? [[Any]] ?? []).flatMap { $0.map { d($0) } }) }

    func testLookAngles() {
        XCTAssertEqual(cases("look_angles").count, 40)
        for (i, c) in cases("look_angles").enumerated() {
            let o = arr(c["observer"]), t = arr(c["target"])
            let la = Geodesy.lookAngles(from: GeoPoint(latDeg: o[0], lonDeg: o[1], heightM: o[2]),
                                        to: GeoPoint(latDeg: t[0], lonDeg: t[1], heightM: t[2]))
            XCTAssertEqual(la.azimuthDeg, d(c["azimuth_deg"]), accuracy: 1e-6, "az \(i)")
            XCTAssertEqual(la.elevationDeg, d(c["elevation_deg"]), accuracy: 1e-6, "el \(i)")
            XCTAssertEqual(la.slantRangeM, d(c["slant_range_m"]), accuracy: 1e-3, "range \(i)")
        }
    }

    func testDeadReckoning() {
        for (i, c) in cases("dead_reckon").enumerated() {
            let inp = c["input"] as? [String: Any] ?? [:]
            let r = Geodesy.deadReckon(
                GeoPoint(latDeg: d(inp["lat"]), lonDeg: d(inp["lon"]), heightM: d(inp["alt_m"])),
                groundSpeedKt: dn(inp["ground_speed_kt"]), trackDeg: dn(inp["track_deg"]),
                verticalRateFpm: dn(inp["vertical_rate_fpm"]), dtS: d(inp["dt_s"])
            )
            let e = arr(c["expected"])
            XCTAssertEqual(r.latDeg, e[0], accuracy: 1e-9, "lat \(i)")
            XCTAssertEqual(r.lonDeg, e[1], accuracy: 1e-9, "lon \(i)")
            XCTAssertEqual(r.heightM, e[2], accuracy: 1e-3, "alt \(i)")
        }
    }

    func testProjection() {
        XCTAssertEqual(cases("projection").count, 60)
        for (i, c) in cases("projection").enumerated() {
            let r = mat(c["r_dw"])
            let view = arr(c["view"])
            let k = Intrinsics.aspectFill(longSideFovDeg: d(c["fov_long_deg"]), imageAspect: d(c["aspect"]),
                                          viewW: view[0], viewH: view[1])
            let ek = arr(c["intrinsics"])
            XCTAssertEqual(k.fx, ek[0], accuracy: 1e-4)
            let w = arr(c["world_dir"])
            let dir = Vec3(w[0], w[1], w[2])
            let p = Projection.project(r, worldDir: dir, k: k, viewW: view[0], viewH: view[1])
            XCTAssertEqual(p.inFront, c["in_front"] as? Bool, "inFront \(i)")
            XCTAssertEqual(p.onScreen, c["on_screen"] as? Bool, "onScreen \(i)")
            if p.inFront {
                XCTAssertEqual(p.x, d(c["x"]), accuracy: 1e-4, "x \(i)")
                XCTAssertEqual(p.y, d(c["y"]), accuracy: 1e-4, "y \(i)")
            }
            XCTAssertEqual(Projection.edgeAngleRad(r, worldDir: dir), d(c["edge_angle_rad"]), accuracy: 1e-9)
        }
    }

    func testRotationsAndReferenceFrame() {
        for c in cases("rotate_about_up") {
            let got = Projection.rotateAboutUp(mat(c["r_dw"]), degreesClockwise: d(c["degrees"])).m
            for (a, b) in zip(got, mat(c["expected"]).m) { XCTAssertEqual(a, b, accuracy: 1e-12) }
        }
        for c in cases("ios_reference_to_enu") {
            let got = Projection.referenceNwuToEnu(mat(c["r_device_to_ref"])).m
            for (a, b) in zip(got, mat(c["expected_r_dw"]).m) { XCTAssertEqual(a, b, accuracy: 1e-12) }
        }
    }
}
